def validSubarraySize(nums: list[int], threshold: int) -> int:
    nums = [0] + nums + [0]
    stack = [0]
    for i in range(1, len(nums)):
        while nums[stack[-1]] > nums[i]:
            val = nums[stack.pop()]
            k = i - stack[-1] - 1
            if val > threshold // k:
                return k
        stack.append(i)
    return -1

